function matrixModal(){modal('Матрица исполнительной документации',`<p>Вид работы: <b>Армирование фундаментной плиты</b></p><div class="checklist">${['Исполнительная геодезическая схема · Геодезия · 1 рабочий день','Сертификаты на арматуру · Входной контроль · 1 рабочий день','Акт входного контроля · Входной контроль · 1 рабочий день','Протоколы сварных соединений · Лаборатория · 2 рабочих дня','Журнал арматурных работ · Производитель работ · 1 рабочий день','Фотографии · Производитель работ · 1 рабочий день','АОСР · ПТО · после поступления обязательных документов'].map(x=>`<div class="check"><span>${x}</span><button class="action">Изменить</button></div>`).join('')}</div>`,`<button class="btn" data-close>Закрыть</button><button class="btn btn-primary" data-close>Сохранить матрицу</button>`)}
