function searchModal(query){let q=query.toLowerCase(), works=state.works.filter(w=>[w.code,w.name,w.structure,w.construction].join(' ').toLowerCase().includes(q)).slice(0,6),tasks=state.tasks.filter(t=>[t.title,t.dept,t.assignee].join(' ').toLowerCase().includes(q)).slice(0,6);modal('Результаты поиска',`<p class="source">Запрос: «${query}» · найдено: ${works.length+tasks.length}</p><div class="checklist">${works.map(w=>`<div class="check"><span><b>${w.name}</b><br><small>Работа ${w.code} · ${w.structure}</small></span><button class="btn btn-sm" data-search-work="${w.id}">Открыть</button></div>`).join('')}${tasks.map(t=>`<div class="check"><span><b>${t.title}</b><br><small>Задача · ${t.dept} · ${t.assignee}</small></span><button class="btn btn-sm" data-search-task="${t.id}">Открыть</button></div>`).join('')||'<p class="empty-note">Ничего не найдено.</p>'}</div>`,`<button class="btn" data-close>Закрыть</button>`);document.querySelectorAll('[data-search-work]').forEach(b=>b.onclick=()=>{modalRoot.innerHTML='';app.innerHTML=detailPage(b.dataset.searchWork);bind()});document.querySelectorAll('[data-search-task]').forEach(b=>b.onclick=()=>taskModal(+b.dataset.searchTask))}
uploadModal=function(){let selectedFile=null;modal('Загрузить документ',`<div class="upload-zone" id="drop-zone"><strong>Перетащите файл сюда или выберите на компьютере</strong><span id="file-caption">Поддерживаются PDF, DOCX, XLSX, JPG, PNG</span><br><input id="file-input" type="file" accept=".pdf,.docx,.xlsx,.jpg,.jpeg,.png" hidden><button class="btn btn-sm" id="choose-file" style="margin-top:10px">Выбрать файл</button></div><div class="card" style="background:#f7fbff;box-shadow:none"><b>✦ Анализ документа ИИ (демонстрация)</b><p>Документ распознан как паспорт качества. Проверьте распознанные данные перед сохранением.</p><div class="form-grid"><div class="field"><label>Наименование документа</label><input id="doc-name" value="Паспорт качества на арматуру А500С"/></div><div class="field"><label>Номер документа</label><input id="doc-number" value="ПС-125/26"/></div><div class="field"><label>Дата</label><input id="doc-date" value="03.07.2026"/></div><div class="field"><label>Изготовитель</label><input value="ООО «Металл-Пром»"/></div><div class="field"><label>Материал / партия</label><input value="Арматура А500С · партия 874"/></div><div class="field"><label>Сооружение</label><select id="doc-structure">${structures.map(x=>`<option>${x}</option>`)}</select></div></div></div>`,`<button class="btn" data-close>Отмена</button><button class="btn btn-primary" id="save-doc">Сохранить документ</button>`);let input=$('#file-input'),zone=$('#drop-zone'),caption=$('#file-caption');let select=file=>{if(!file)return;let ext=file.name.split('.').pop().toLowerCase();if(!['pdf','docx','xlsx','jpg','jpeg','png'].includes(ext)){toast('Поддерживаются только PDF, DOCX, XLSX, JPG и PNG.');return}selectedFile=file;caption.textContent='Выбран файл: '+file.name+' · '+Math.ceil(file.size/1024)+' КБ';zone.style.borderColor='var(--green)';zone.style.background='#f0fbf5'};$('#choose-file').onclick=()=>input.click();input.onchange=()=>select(input.files[0]);zone.ondragover=e=>{e.preventDefault();zone.style.borderColor='var(--blue)'};zone.ondragleave=()=>{if(!selectedFile)zone.style.borderColor=''};zone.ondrop=e=>{e.preventDefault();select(e.dataTransfer.files[0])};$('#save-doc').onclick=()=>{let name=$('#doc-name').value.trim();if(!name)return toast('Укажите наименование документа.');let fileName=selectedFile?selectedFile.name:'Демонстрационный_паспорт_качества.pdf';state.uploads.unshift({kind:state.page,name,number:$('#doc-number').value,date:$('#doc-date').value,structure:$('#doc-structure').value,type:'Паспорт качества',file:fileName});logEvent('Загружена новая версия документа: '+name);modalRoot.innerHTML='';render();toast('Документ сохранён как новая версия и направлен на проверку.')}}
settingsPage=function(){return shell(heading('Настройки','Параметры проекта, уведомлений и матрицы ИД')+`<div class="grid-2"><div class="card"><h2>Матрица исполнительной документации</h2><p>Для каждого вида работ настройте обязательные документы, ответственных и нормативные сроки.</p><button class="btn btn-primary" id="matrix">Открыть матрицу ИД</button></div><div class="card"><h2>Уведомления</h2><div class="checklist">${['Новые задачи','Приближение срока','Просроченные задачи','Документы с замечаниями'].map(x=>`<div class="check"><span>${x}</span><input type="checkbox" checked></div>`).join('')}</div></div></div><div class="card"><h2>Данные MVP</h2><p class="source">Экспортируйте локальные данные перед очисткой браузера или импортируйте ранее сохранённую резервную копию.</p><input id="import-backup-input" type="file" accept="application/json,.json" hidden><button class="btn" id="export-backup">Скачать резервную копию</button><button class="btn" id="import-backup">Импортировать данные</button><button class="btn btn-danger" id="reset-data">Сбросить локальные данные</button></div>`)}
