function directoryItems(name){if(name==='Шаблоны АОСР'&&typeof aosrTemplateDefinitions!=='undefined')return Object.values(aosrTemplateDefinitions).map(t=>t.name);return state.directoryValues[name]||directoryDefinitions[name]||[]}
function directoryDetail(name){let values=directoryItems(name);return shell(heading(name,'Настройка значений справочника',`<button class="btn btn-primary" id="add-directory-value">＋ Добавить значение</button>`)+`<button class="btn btn-sm" id="back-to-directories">← Все разделы</button><div class="card" style="margin-top:12px"><div class="table-wrap"><table class="table"><thead><tr><th>Наименование</th><th>Статус</th><th>Источник</th><th></th></tr></thead><tbody>${values.map((v,i)=>`<tr><td><b>${v}</b></td><td><span class="status done">Активен</span></td><td>${state.directoryValues[name]?'Добавлено пользователем':'Тестовые данные'}</td><td><button class="action" data-remove-directory-value="${i}">Удалить</button></td></tr>`).join('')||'<tr><td colspan="4" class="empty-note">В справочнике пока нет значений.</td></tr>'}</tbody></table></div></div>`)}
directoryPage=function(kind){if(kind!=='Справочники')return directoryPageCore(kind);let names=Object.keys(directoryDefinitions);return shell(heading('Справочники','Настройка нормативно-справочной информации проекта')+`<div class="report-grid">${names.map(name=>`<button class="report" data-directory="${name}" style="text-align:left"><b>${name}</b><div class="num">${directoryItems(name).length}</div><small style="color:var(--muted)">Записей · открыть раздел</small></button>`).join('')}</div><div class="card" style="margin-top:18px"><h2>Матрица исполнительной документации</h2><p>В настройках матрицы задаются обязательные документы, подразделения, нормативные сроки и последовательность задач для вида работ.</p><button class="btn btn-primary" data-page="Настройки">Открыть матрицу ИД</button></div>`)}
