function aosrTemplateCatalog(){return shell(heading('Шаблоны АОСР','Демонстрационные шаблоны по рекомендуемому образцу Минстроя России')+`<div class="card"><div class="critical orange">Перед выпуском проверьте реквизиты сторон, полномочия подписантов, проектную документацию и применимость нормативных документов к конкретной работе.</div><p class="source">Нормативная основа: приложение № 3 к составу исполнительной документации, утверждённому приказом Минстроя России от 16.05.2023 № 344/пр (ред. от 23.06.2025).</p><div class="checklist">${Object.entries(aosrTemplateDefinitions).map(([key,t])=>`<div class="check"><span><b>${t.name}</b><br><small>${t.place} · ${t.number}</small></span><button class="btn btn-sm" data-aosr-template="${key}">Открыть</button></div>`).join('')}</div></div>`)}
function aosrTemplateDetail(key){let t=aosrTemplateDefinitions[key];return shell(heading(t.name,'Заполненный демонстрационный шаблон АОСР',`<button class="btn" id="back-to-aosr-templates">← К шаблонам</button>`)+`<div class="card"><p class="source">Рекомендуемый образец: приложение № 3 к приказу Минстроя России № 344/пр. Поля с персональными реквизитами подписантов должны быть заполнены по документам проекта.</p><div class="checklist"><div class="check"><span>Объект капитального строительства</span><b>Строительство гидротехнического сооружения</b></div><div class="check"><span>Номер и дата акта</span><b>${t.number} · 13.07.2026</b></div><div class="check"><span>Место выполнения работ</span><b>${t.place}</b></div><div class="check"><span>1. Предъявленные скрытые работы</span><b>${t.work}</b></div><div class="check"><span>2. Проектная / рабочая документация</span><b>${t.rd}</b></div><div class="check"><span>3. Материалы и документы качества</span><b>${t.materials}</b></div><div class="check"><span>4. Документы соответствия работ</span><b>${t.evidence}</b></div><div class="check"><span>5. Даты начала и окончания</span><b>${t.dates}</b></div><div class="check"><span>6. Технические регламенты и нормы</span><b>${t.norms}</b></div><div class="check"><span>7. Разрешённые последующие работы</span><b>${t.next}</b></div><div class="check"><span>Приложения</span><b>${t.appendix}</b></div><div class="check"><span>Подписанты</span><b>Застройщик / технический заказчик (стройконтроль); лицо, осуществляющее строительство; исполнитель работ — при наличии отдельного договора</b></div></div><div style="margin-top:15px"><button class="btn btn-primary" data-use-aosr-template="${key}">Использовать в предварительном АОСР</button></div></div>`)}
const directoryDetailCore=directoryDetail;
directoryDetail=function(name){return name==='Шаблоны АОСР'?aosrTemplateCatalog():directoryDetailCore(name)}
function toast(text){let old=$('.toast');if(old)old.remove();let e=document.createElement('div');e.className='toast';e.textContent=text;document.body.append(e);setTimeout(()=>e.remove(),4400)}
const bindCore=bind;
