downloadDemoAosr=function(w){let title=escAosr(w.name),place=escAosr(`${w.structure}${w.section?' · '+w.section:''}${w.construction?' · '+w.construction:''}`),date=escAosr(w.date),code=escAosr(w.code||'____'),html=`<!doctype html><html lang="ru"><head><meta charset="utf-8"><title>АОСР ${code}</title><style>@page{size:A4;margin:18mm 15mm 16mm}body{font:11pt/1.32 'Times New Roman',serif;color:#000;margin:0}p{margin:5px 0}.right{text-align:right}.center{text-align:center}.title{font-size:14pt;font-weight:700;margin:16px 0 12px}.field{border-bottom:1px solid #000;min-height:20px;padding:2px 0}.hint{font-size:8.5pt;font-style:italic;text-align:center}.section{margin-top:10px}.sign{width:100%;border-collapse:collapse;margin-top:14px}.sign td{vertical-align:bottom;padding:7px 5px;border-bottom:1px solid #000}.sign .role{width:55%;border-bottom:0;padding-top:13px}.sign .line{width:20%;text-align:center}.sign .name{width:25%;text-align:center}.note{font-size:8.5pt;color:#333;margin-top:12px}.no-print{margin:0 0 15px;font:13px Arial}@media print{.no-print{display:none}}</style></head><body><div class="no-print"><button onclick="window.print()">Печать / Сохранить PDF</button></div><div class="right">Приложение № 3<br>к составу исполнительной документации,<br>утверждённому приказом Минстроя России<br>от 16.05.2023 № 344/пр</div><p class="section"><b>Объект капитального строительства</b></p><div class="field">Строительство гидротехнического сооружения</div><div class="hint">(наименование объекта в соответствии с проектной документацией, адрес объекта)</div><div class="center title">АКТ<br>освидетельствования скрытых работ</div><p class="right">№ ${code}&nbsp;&nbsp;&nbsp;&nbsp; «${date}»</p><p class="section"><b>Представитель застройщика, технического заказчика, лица, ответственного за эксплуатацию, или регионального оператора по вопросам строительного контроля</b></p><div class="field">[Заполняется по распорядительному документу и реквизитам организации]</div><p><b>Представитель лица, осуществляющего строительство, реконструкцию, капитальный ремонт</b></p><div class="field">[Заполняется по распорядительному документу и реквизитам организации]</div><p><b>Представитель лица, выполнившего работы, подлежащие освидетельствованию</b> (при наличии отдельного договора)</p><div class="field">[Заполняется при применимости]</div><p class="section">произвели осмотр работ, выполненных лицом, осуществляющим строительство, и составили настоящий акт о нижеследующем:</p><div class="section"><b>1. К освидетельствованию предъявлены следующие работы:</b><div class="field">${title}</div></div><div class="section"><b>2. Работы выполнены по проектной документации:</b><div class="field">Рабочая документация: [шифр РД и листы — заполнить по проекту]</div></div><div class="section"><b>3. При выполнении работ применены:</b><div class="field">Материалы, изделия и документы, подтверждающие их качество: [заполнить по реестру документов качества]</div></div><div class="section"><b>4. Предъявлены документы, подтверждающие соответствие работ предъявляемым требованиям:</b><div class="field">Исполнительные схемы, результаты испытаний, акты входного контроля, записи ОЖР: [заполнить по комплекту ИД]</div></div><div class="section"><b>5. Даты начала и окончания работ:</b><div class="field">Дата окончания: ${date}. Дату начала заполнить по ОЖР.</div></div><div class="section"><b>6. Работы выполнены в соответствии с:</b><div class="field">Проектной и рабочей документацией; применимыми техническими регламентами, СП и стандартами.</div></div><div class="section"><b>7. Разрешается производство последующих работ:</b><div class="field">[Указать следующую работу / конструкцию / участок сети по проекту]</div></div><div class="section"><b>Дополнительные сведения:</b><div class="field">Место выполнения работ: ${place}</div></div><div class="section"><b>Приложения:</b><div class="field">Исполнительные схемы, документы качества, результаты испытаний, выписки из журналов — согласно фактическому комплекту ИД.</div></div><table class="sign"><tr><td class="role">Представитель застройщика / технического заказчика / лица, ответственного за эксплуатацию, или регионального оператора по вопросам строительного контроля</td><td class="line">подпись</td><td class="name">фамилия, инициалы</td></tr><tr><td class="role">Представитель лица, осуществляющего строительство</td><td class="line">подпись</td><td class="name">фамилия, инициалы</td></tr><tr><td class="role">Представитель лица, выполнившего работы (при применимости)</td><td class="line">подпись</td><td class="name">фамилия, инициалы</td></tr></table><p class="note">Печатная форма подготовлена по структуре рекомендуемого образца приложения № 3 к приказу Минстроя России № 344/пр. Поля в квадратных скобках требуют проверки и заполнения уполномоченным пользователем; они не формируются автоматически.</p></body></html>`;let blob=new Blob([html],{type:'text/html;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='АОСР_'+code+'_печатная_форма.html';a.click();URL.revokeObjectURL(a.href);logEvent('Сформирована печатная форма АОСР по приложению № 3 к приказу № 344/пр.',w.id);toast('Скачана печатная форма АОСР. Откройте её и используйте «Печать / Сохранить PDF».')};
function structureStatus(structure){let works=state.works.filter(w=>w.structure===structure),ids=new Set(works.map(w=>w.id)),tasks=state.tasks.filter(t=>ids.has(t.work)),ready=works.length?Math.round(works.reduce((sum,w)=>sum+w.ready,0)/works.length):0,missing=works.reduce((sum,w)=>sum+w.missing,0),overdue=tasks.filter(t=>t.status==='Просрочена').length;return {works,tasks,ready,missing,overdue,complete:works.filter(w=>w.ready===100).length}}
structuresPage=function(){return shell(heading('Сооружения','Выберите сооружение, чтобы увидеть подготовку исполнительной документации')+`<div class="report-grid">${structures.map(s=>{let x=structureStatus(s);return `<button class="report" data-structure="${s}" style="text-align:left"><b>${s}</b><div class="num">${x.ready}%</div><div class="mini-bar"><i style="width:${x.ready}%"></i></div><small style="color:var(--muted);display:block;margin-top:8px">Работ: ${x.works.length} · документов отсутствует: ${x.missing}</small><small style="color:${x.overdue?'var(--red)':'var(--green)'};display:block;margin-top:4px">${x.overdue?'Просрочено задач: '+x.overdue:'Просрочек нет'}</small></button>`}).join('')}</div>`)}
function structureDetail(structure){let x=structureStatus(structure);return shell(heading(structure,'Текущий статус подготовки исполнительной документации',`<button class="btn" id="back-to-structures">← Все сооружения</button>`)+`<div class="kpis"><div class="kpi"><div class="kpi-label">Средняя готовность ИД</div><div class="kpi-value">${x.ready}%</div></div><div class="kpi"><div class="kpi-label">Выполнено работ</div><div class="kpi-value">${x.works.length}</div></div><div class="kpi"><div class="kpi-label">Полностью готово</div><div class="kpi-value" style="color:var(--green)">${x.complete}</div></div><div class="kpi"><div class="kpi-label">Отсутствует документов</div><div class="kpi-value" style="color:${x.missing?'var(--orange)':'var(--green)'}">${x.missing}</div></div><div class="kpi"><div class="kpi-label">Просрочено задач</div><div class="kpi-value" style="color:${x.overdue?'var(--red)':'var(--green)'}">${x.overdue}</div></div><div class="kpi"><div class="kpi-label">Задач на проверке</div><div class="kpi-value">${x.tasks.filter(t=>t.status==='На проверке').length}</div></div></div><div class="grid-2"><div class="card"><h2>Работы и готовность ИД</h2>${worksTable(x.works)}</div><div class="card"><h2>Задачи, требующие внимания</h2>${x.tasks.filter(t=>t.status!=='Выполнена').map(t=>`<div class="check interactive-structure-task" data-structure-task="${t.id}" tabindex="0"><span><b>${t.title}</b><br><small>${t.dept} · срок ${t.due}</small></span><span class="status ${statusClass(t.status)}">${t.status}</span></div>`).join('')||'<p class="empty-note">Активных задач нет.</p>'}</div></div><div class="card"><h2>Документы, требующие внимания</h2>${x.works.filter(w=>w.missing>0).map(w=>`<div class="check" data-work="${w.id}" style="cursor:pointer"><span><b>${w.name}</b><br><small>${w.section} · готовность ИД ${w.ready}%</small></span><span class="status waiting">Не хватает: ${w.missing}</span></div>`).join('')||'<p class="empty-note">По всем работам комплект документов сформирован.</p>'}</div>`)}
const bindStructureDetails=bind;
bind=function(){bindStructureDetails();document.querySelectorAll('[data-structure]').forEach(b=>b.onclick=()=>{app.innerHTML=structureDetail(b.dataset.structure);bind()});let back=$('#back-to-structures');if(back)back.onclick=()=>{state.page='Сооружения';save();render()};document.querySelectorAll('[data-structure-task]').forEach(row=>{row.style.cursor='pointer';row.onclick=()=>taskModal(+row.dataset.structureTask);row.onkeydown=e=>{if(e.key==='Enter'||e.key===' ')taskModal(+row.dataset.structureTask)}})};
state.structureFilter ||= {readiness:'',overdue:''};
structuresPage=function(){let f=state.structureFilter,items=structures.map(s=>({name:s,status:structureStatus(s)})).filter(x=>(!f.readiness||(f.readiness==='low'?x.status.ready<50:f.readiness==='medium'?x.status.ready>=50&&x.status.ready<80:x.status.ready>=80))&&(!f.overdue||(f.overdue==='yes'?x.status.overdue>0:x.status.overdue===0)));return shell(heading('Сооружения','Выберите сооружение, чтобы увидеть подготовку исполнительной документации')+`<div class="filters"><select id="structure-readiness"><option value="">Любая готовность ИД</option><option value="low" ${f.readiness==='low'?'selected':''}>До 50%</option><option value="medium" ${f.readiness==='medium'?'selected':''}>50–79%</option><option value="high" ${f.readiness==='high'?'selected':''}>80% и выше</option></select><select id="structure-overdue"><option value="">Любые задачи</option><option value="yes" ${f.overdue==='yes'?'selected':''}>Есть просроченные задачи</option><option value="no" ${f.overdue==='no'?'selected':''}>Без просрочек</option></select><button class="btn" id="clear-structure-filter">Сбросить</button></div><div class="source" style="margin-bottom:12px">Найдено сооружений: ${items.length}</div><div class="report-grid">${items.map(({name:s,status:x})=>`<button class="report" data-structure="${s}" style="text-align:left"><b>${s}</b><div class="num">${x.ready}%</div><div class="mini-bar"><i style="width:${x.ready}%"></i></div><small style="color:var(--muted);display:block;margin-top:8px">Работ: ${x.works.length} · документов отсутствует: ${x.missing}</small><small style="color:${x.overdue?'var(--red)':'var(--green)'};display:block;margin-top:4px">${x.overdue?'Просрочено задач: '+x.overdue:'Просрочек нет'}</small></button>`).join('')||'<p class="empty-note">По заданным фильтрам сооружения не найдены.</p>'}</div>`)}
const bindStructureFilter=bind;
bind=function(){bindStructureFilter();let readiness=$('#structure-readiness'),overdue=$('#structure-overdue'),clear=$('#clear-structure-filter');if(readiness)readiness.onchange=e=>{state.structureFilter.readiness=e.target.value;save();render()};if(overdue)overdue.onchange=e=>{state.structureFilter.overdue=e.target.value;save();render()};if(clear)clear.onclick=()=>{state.structureFilter={readiness:'',overdue:''};save();render()}};
uploadModal=function(){let selectedFile=null;modal('Загрузить документ',`<div class="upload-zone" id="drop-zone"><strong>Перетащите файл сюда или выберите на компьютере</strong><span id="file-caption">PDF, DOCX, XLSX, JPG, PNG</span><br><input id="file-input" type="file" accept=".pdf,.docx,.xlsx,.jpg,.jpeg,.png" hidden><button class="btn btn-sm" id="choose-file" style="margin-top:10px">Выбрать файл</button></div><div class="form-grid"><div class="field"><label>Наименование документа</label><input id="doc-name" value="Паспорт качества на арматуру А500С"/></div><div class="field"><label>Номер документа</label><input id="doc-number" value="ПС-125/26"/></div><div class="field"><label>Дата</label><input id="doc-date" value="03.07.2026"/></div><div class="field"><label>Сооружение</label><select id="doc-structure">${structures.map(x=>`<option>${x}</option>`)}</select></div><div class="field full"><label>Связанные выполненные работы</label><div class="checklist" style="max-height:190px;overflow:auto">${state.works.map(w=>`<label class="check"><span><b>${w.code}</b> · ${w.name}<br><small>${w.structure}</small></span><input class="doc-link-work" type="checkbox" value="${w.id}"></label>`).join('')}</div></div></div>`,`<button class="btn" data-close>Отмена</button><button class="btn btn-primary" id="save-doc">Сохранить документ</button>`);let input=$('#file-input'),zone=$('#drop-zone'),caption=$('#file-caption'),select=file=>{if(!file)return;let ext=file.name.split('.').pop().toLowerCase();if(!['pdf','docx','xlsx','jpg','jpeg','png'].includes(ext))return toast('Поддерживаются только PDF, DOCX, XLSX, JPG и PNG.');selectedFile=file;caption.textContent='Выбран файл: '+file.name;zone.style.borderColor='var(--green)'};$('#choose-file').onclick=()=>input.click();input.onchange=()=>select(input.files[0]);zone.ondragover=e=>e.preventDefault();zone.ondrop=e=>{e.preventDefault();select(e.dataTransfer.files[0])};$('#save-doc').onclick=()=>{let name=$('#doc-name').value.trim(),linkedWorks=[...document.querySelectorAll('.doc-link-work:checked')].map(x=>Number(x.value));if(!name)return toast('Укажите наименование документа.');if(!linkedWorks.length)return toast('Выберите хотя бы одну связанную выполненную работу.');state.uploads.unshift({kind:state.page,name,number:$('#doc-number').value,date:$('#doc-date').value,structure:$('#doc-structure').value,type:'Паспорт качества',file:selectedFile?selectedFile.name:'Демонстрационный_паспорт_качества.pdf',linkedWorks});logEvent('Загружена новая версия документа: '+name);modalRoot.innerHTML='';render();toast('Документ сохранён и привязан к '+linkedWorks.length+' работам.')}}
documentsPage=function(kind){let data={'Исполнительная документация':['Исполнительная документация','Комплектность по выполненным работам'],'Документы качества':['Документы качества','Реестр паспортов, сертификатов и актов входного контроля'],'Геодезические документы':['Геодезические документы','Реестр исполнительных схем и отчётов'],'Лабораторные протоколы':['Лабораторные протоколы','Реестр испытаний строительной лаборатории']}[kind],added=state.uploads.filter(d=>d.kind===kind),action=allowed('upload')?`<button class="btn btn-primary" id="upload-document">＋ Загрузить документ</button>`:'';return shell(heading(data[0],data[1],action)+(!allowed('upload')?accessHint('upload'):'')+`<div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Наименование документа</th><th>Номер</th><th>Дата</th><th>Сооружение</th><th>Связанные работы</th><th>Статус проверки</th><th>Файл</th></tr></thead><tbody>${added.map(d=>`<tr><td><b>${d.name}</b><br><span style="color:var(--muted)">${d.type}</span></td><td>${d.number}</td><td>${d.date}</td><td>${d.structure}</td><td>${d.linkedWorks?.length||1}</td><td><span class="status review">На проверке</span></td><td><button class="action">${d.file}</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty-note">Загруженных пользователем документов пока нет.</td></tr>'}</tbody></table></div></div>`)}
const bindDocumentLinks=bind;
bind=function(){bindDocumentLinks();let upload=$('#upload-document');if(upload)upload.onclick=uploadModal};
documentsPage=function(kind){let data={'Исполнительная документация':['Исполнительная документация','Комплектность по выполненным работам'],'Документы качества':['Документы качества','Реестр паспортов, сертификатов и актов входного контроля'],'Геодезические документы':['Геодезические документы','Реестр исполнительных схем и отчётов'],'Лабораторные протоколы':['Лабораторные протоколы','Реестр испытаний строительной лаборатории']}[kind],added=state.uploads.filter(d=>d.kind===kind),action=allowed('upload')?`<button class="btn btn-primary" id="upload-document">＋ Загрузить документ</button>`:'';return shell(heading(data[0],data[1],action)+(!allowed('upload')?accessHint('upload'):'')+`<div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Наименование документа</th><th>Номер</th><th>Дата</th><th>Сооружение</th><th>Связанные работы</th><th>Статус проверки</th><th>Файл</th><th></th></tr></thead><tbody>${added.map(d=>{let index=state.uploads.indexOf(d),status=d.reviewStatus||'На проверке';return `<tr><td><b>${d.name}</b><br><span style="color:var(--muted)">${d.type}</span></td><td>${d.number}</td><td>${d.date}</td><td>${d.structure}</td><td>${d.linkedWorks?.length||1}</td><td><span class="status ${statusClass(status)}">${status}</span>${d.reviewComment?`<br><small style="color:var(--muted)">${d.reviewComment}</small>`:''}</td><td><button class="action">${d.file}</button></td><td><button class="action" data-doc-review="${index}">Проверить</button></td></tr>`}).join('')||'<tr><td colspan="8" class="empty-note">Загруженных пользователем документов пока нет.</td></tr>'}</tbody></table></div></div>`)}
function documentReviewModal(index){let doc=state.uploads[index];modal('Проверка документа',`<p><b>${doc.name}</b><br><span class="source">${doc.number} · ${doc.structure} · связанных работ: ${doc.linkedWorks?.length||1}</span></p><div class="field"><label>Комментарий проверяющего</label><textarea id="doc-review-comment" placeholder="Укажите замечание при возврате документа"></textarea></div>`,`<button class="btn" data-close>Закрыть</button><button class="btn btn-danger" id="return-doc">Вернуть с замечанием</button><button class="btn btn-primary" id="accept-doc">Принять документ</button>`);$('#return-doc').onclick=()=>{let comment=$('#doc-review-comment').value.trim();if(!comment)return toast('Укажите причину возврата документа.');doc.reviewStatus='Возвращён с замечаниями';doc.reviewComment=comment;logEvent('Документ возвращён с замечаниями: '+doc.name);modalRoot.innerHTML='';render();toast('Документ возвращён с замечаниями.')};$('#accept-doc').onclick=()=>{doc.reviewStatus='Принят';doc.reviewComment='';logEvent('Документ принят: '+doc.name);modalRoot.innerHTML='';render();toast('Документ принят.')}}
const bindDocumentReview=bind;
