function workJournalPage(){let canEdit=canFillWorkJournal(),entries=state.workJournal.map(item=>`<tr><td>${auditEsc(item.date)}</td><td>${auditEsc(item.section)}</td><td><b>${auditEsc(item.work)}</b><br><small>${auditEsc(item.description)}</small></td><td>${auditEsc(item.materials)||'—'}</td><td>${auditEsc(item.attachments)||'—'}</td><td>${auditEsc(item.author)}</td></tr>`).join('');let action=`<div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn" id="download-journal-xml">⇩ XML</button><button class="btn" id="print-work-journal">Печать / PDF</button>${canEdit?'<button class="btn btn-primary" id="add-journal-entry">＋ Новая запись</button>':''}</div>`;return shell(heading('Общий журнал работ','Электронный журнал по форме и порядку приказа Минстроя России от 02.12.2022 № 1026/пр',action)+`<div class="source" style="margin-bottom:15px">Форма действует с 01.09.2023 до 01.09.2029. Электронный журнал должен проверяться на совместимость с информационной системой принимающего органа.</div><div class="card"><div class="detail-hero"><h1>Общий журнал № ОЖР-001</h1><div class="meta"><span>Объект: строительство гидротехнического сооружения</span><span>Застройщик: демонстрационные данные</span><span>Уполномоченное лицо: Петров П.П.</span></div></div><div class="report-grid">${[[1,'ИТР'],[2,'Специальные журналы'],[3,'Выполненные работы'],[4,'Строительный контроль'],[5,'Исполнительная документация'],[6,'Госстройнадзор']].map(item=>`<button class="report" data-work-journal-section="${item[0]}" style="text-align:left"><b>Раздел ${item[0]}</b><small style="display:block;color:var(--muted);margin-top:7px">${item[1]}</small></button>`).join('')}</div></div><div class="card"><div class="card-head"><h2>Раздел 3. Сведения о выполнении работ</h2><span class="source">Записей: ${state.workJournal.length}</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Дата</th><th>Участок</th><th>Выполненные работы и сведения</th><th>Материалы</th><th>Приложения</th><th>Автор</th></tr></thead><tbody>${entries||'<tr><td colspan="6" class="empty-note">Записей пока нет.</td></tr>'}</tbody></table></div></div>`)}
