state.workspaceLayout ||= {};
function workspaceConfig(){let key=state.role,available=availableRolePages(),saved=state.workspaceLayout[key]||{},order=Array.isArray(saved.order)?saved.order.filter(page=>available.includes(page)&&page!=='Главная'):available.filter(page=>page!=='Главная'),missing=available.filter(page=>page!=='Главная'&&!order.includes(page));return {order:[...order,...missing],hidden:Array.isArray(saved.hidden)?saved.hidden.filter(page=>available.includes(page)&&page!=='Главная'):[]}}
