function workspaceSettingsModal(){let config=workspaceConfig(),draw=()=>{let body=$('#workspace-items');if(!body)return;body.innerHTML=config.order.map((page,index)=>`<div class="check"><label style="display:flex;gap:9px;align-items:center;flex:1"><input type="checkbox" data-workspace-visible="${page}" ${config.hidden.includes(page)?'':'checked'}><span><b>${page}</b><br><small>${config.hidden.includes(page)?'Скрыта из панели':'Отображается в панели'}</small></span></label><button class="btn btn-sm" data-workspace-up="${index}" ${index===0?'disabled':''}>↑</button><button class="btn btn-sm" data-workspace-down="${index}" ${index===config.order.length-1?'disabled':''}>↓</button></div>`).join('');body.querySelectorAll('[data-workspace-visible]').forEach(input=>input.onchange=()=>{let page=input.dataset.workspaceVisible;config.hidden=input.checked?config.hidden.filter(item=>item!==page):[...config.hidden,page];draw()});body.querySelectorAll('[data-workspace-up]').forEach(button=>button.onclick=()=>{let index=Number(button.dataset.workspaceUp);[config.order[index-1],config.order[index]]=[config.order[index],config.order[index-1]];draw()});body.querySelectorAll('[data-workspace-down]').forEach(button=>button.onclick=()=>{let index=Number(button.dataset.workspaceDown);[config.order[index],config.order[index+1]]=[config.order[index+1],config.order[index]];draw()})};modal('Настройка рабочего пространства',`<p class="source">«Главная» закреплена. Меняйте порядок и видимость остальных доступных для вашей роли разделов.</p><div class="check" style="margin-bottom:9px"><span><b>Главная</b><br><small>Закреплённая вкладка</small></span><span class="status done">Всегда видна</span></div><div class="checklist" id="workspace-items"></div>`,`<button class="btn" id="workspace-reset">Сбросить</button><button class="btn" data-close>Отмена</button><button class="btn btn-primary" id="workspace-save">Сохранить</button>`);draw();$('#workspace-reset').onclick=()=>{config={order:availableRolePages().filter(page=>page!=='Главная'),hidden:[]};draw()};$('#workspace-save').onclick=()=>{saveWorkspaceConfig(config);modalRoot.innerHTML='';render();toast('Рабочее пространство настроено для роли: '+state.role+'.')}}
