function matrixDeadlineModal(key){let item=matrixRequirements.find(requirement=>requirement.key===key);if(!item)return;modal('Срок подготовки документа',`<p><b>${item.name}</b><br><span class="source">Ответственный: ${item.department}</span></p><div class="field"><label>Нормативный срок, рабочих дней</label><input id="matrix-deadline-value" type="number" min="0" max="365" value="${matrixDeadline(item)}"></div><p class="source">Срок отсчитывается от даты внесения выполненной работы. Значение 0 означает «в день выполнения работ».</p>`,`<button class="btn" data-close>Отмена</button><button class="btn btn-primary" id="save-matrix-deadline">Сохранить</button>`);$('#save-matrix-deadline').onclick=()=>{let value=Number($('#matrix-deadline-value').value);if(!Number.isInteger(value)||value<0||value>365)return toast('Укажите целое число от 0 до 365 рабочих дней.');state.matrixDeadlines[key]=value;logEvent('Изменён срок в матрице ИД: '+item.name+' — '+value+' раб. дн.');modalRoot.innerHTML='';matrixModal();toast('Срок сохранён в матрице ИД.')}}
matrixModal=function(){modal('Матрица исполнительной документации',`<p>Вид работы: <b>Армирование фундаментной плиты</b></p><p class="source">Настраиваются сроки подготовки обязательных документов. Изменённые сроки сохраняются для проекта.</p><div class="table-wrap"><table class="table"><thead><tr><th>Документ</th><th>Ответственный</th><th>Срок</th><th></th></tr></thead><tbody>${matrixRequirements.map(item=>`<tr><td><b>${item.name}</b></td><td>${item.department}</td><td>${matrixDeadline(item)} раб. дн.</td><td><button class="action" data-matrix-edit="${item.key}">Изменить</button></td></tr>`).join('')}</tbody></table></div>`,`<button class="btn" id="matrix-reset">Сбросить сроки</button><button class="btn btn-primary" data-close>Готово</button>`);document.querySelectorAll('[data-matrix-edit]').forEach(button=>button.onclick=()=>matrixDeadlineModal(button.dataset.matrixEdit));$('#matrix-reset').onclick=()=>{state.matrixDeadlines={};save();matrixModal();toast('Сроки матрицы возвращены к значениям по умолчанию.')}};
function addBusinessDays(isoDate,days){let date=new Date(isoDate+'T12:00:00'),left=Number(days);while(left>0){date.setDate(date.getDate()+1);if(date.getDay()!==0&&date.getDay()!==6)left--}return date.toLocaleDateString('ru-RU')}
const matrixKeyByDepartment={'Геодезическая служба':'survey','Входной контроль':'certificate','Строительная лаборатория':'welding','ПТО':'aosr'};
const workModalBeforeMatrixDeadlines=workModal;
workModal=function(){workModalBeforeMatrixDeadlines();let saveWork=$('#save-work');if(!saveWork)return;let originalSave=saveWork.onclick;saveWork.onclick=()=>{let previousMax=Math.max(...state.works.map(work=>work.id)),completionDate=$('#w-date')?.value;originalSave();let createdWork=state.works.find(work=>work.id>previousMax);if(!createdWork||!completionDate)return;state.tasks.filter(task=>task.work===createdWork.id).forEach(task=>{let key=matrixKeyByDepartment[task.dept],item=matrixRequirements.find(requirement=>requirement.key===key);if(item)task.due=addBusinessDays(completionDate,matrixDeadline(item))});save();render()}}
state.matrixSequence ||= {};
function matrixStage(item){let value=Number(state.matrixSequence[item.key]);return Number.isInteger(value)&&value>0?value:(item.key==='aosr'?2:1)}
matrixDeadlineModal=function(key){let item=matrixRequirements.find(requirement=>requirement.key===key);if(!item)return;modal('Настройка позиции матрицы',`<p><b>${item.name}</b><br><span class="source">Ответственный: ${item.department}</span></p><div class="form-grid"><div class="field"><label>Срок, рабочих дней</label><input id="matrix-deadline-value" type="number" min="0" max="365" value="${matrixDeadline(item)}"></div><div class="field"><label>Этап запуска задачи</label><input id="matrix-sequence-value" type="number" min="1" max="20" value="${matrixStage(item)}"></div></div><p class="source">Задачи этапа 1 запускаются сразу. Задача следующего этапа открывается после завершения всех задач предыдущих этапов по этой работе.</p>`,`<button class="btn" data-close>Отмена</button><button class="btn btn-primary" id="save-matrix-deadline">Сохранить</button>`);$('#save-matrix-deadline').onclick=()=>{let deadline=Number($('#matrix-deadline-value').value),stage=Number($('#matrix-sequence-value').value);if(!Number.isInteger(deadline)||deadline<0||deadline>365||!Number.isInteger(stage)||stage<1||stage>20)return toast('Укажите срок от 0 до 365 и этап от 1 до 20.');state.matrixDeadlines[key]=deadline;state.matrixSequence[key]=stage;logEvent('Изменена матрица ИД: '+item.name+' — '+deadline+' раб. дн., этап '+stage+'.');modalRoot.innerHTML='';matrixModal();toast('Параметры матрицы сохранены.')}};
matrixModal=function(){modal('Матрица исполнительной документации',`<p>Вид работы: <b>Армирование фундаментной плиты</b></p><p class="source">Этап задаёт последовательность старта: следующий этап будет разблокирован после завершения задач предыдущих этапов.</p><div class="table-wrap"><table class="table"><thead><tr><th>Документ</th><th>Ответственный</th><th>Срок</th><th>Этап</th><th></th></tr></thead><tbody>${matrixRequirements.map(item=>`<tr><td><b>${item.name}</b></td><td>${item.department}</td><td>${matrixDeadline(item)} раб. дн.</td><td><span class="status ${matrixStage(item)===1?'progress':'waiting'}">${matrixStage(item)}</span></td><td><button class="action" data-matrix-edit="${item.key}">Изменить</button></td></tr>`).join('')}</tbody></table></div>`,`<button class="btn" id="matrix-reset">Сбросить</button><button class="btn btn-primary" data-close>Готово</button>`);document.querySelectorAll('[data-matrix-edit]').forEach(button=>button.onclick=()=>matrixDeadlineModal(button.dataset.matrixEdit));$('#matrix-reset').onclick=()=>{state.matrixDeadlines={};state.matrixSequence={};save();matrixModal();toast('Сроки и этапы матрицы возвращены к значениям по умолчанию.')}};
function unlockDependentTasks(){let released=0;state.tasks.forEach(task=>{if(!task.blocked||!task.dependsOn?.length)return;let dependencies=task.dependsOn.map(id=>state.tasks.find(item=>item.id===id));if(dependencies.length&&dependencies.every(item=>item?.status==='Выполнена')){task.blocked=false;task.status='Новая';released++;logEvent('Разблокирована задача следующего этапа: '+task.title+'.',task.work)}});if(released)save();return released}
const workModalBeforeDependencies=workModal;
workModal=function(){workModalBeforeDependencies();let button=$('#save-work');if(!button)return;let original=button.onclick;button.onclick=()=>{let previousWorkId=Math.max(...state.works.map(work=>work.id));original();let work=state.works.find(item=>item.id>previousWorkId);if(!work)return;let batch=state.tasks.filter(task=>task.work===work.id);batch.forEach(task=>{let key=matrixKeyByDepartment[task.dept],item=matrixRequirements.find(requirement=>requirement.key===key);task.matrixKey=key||'';task.sequence=item?matrixStage(item):1});batch.forEach(task=>{task.dependsOn=batch.filter(other=>other.sequence<task.sequence).map(other=>other.id);task.blocked=task.dependsOn.length>0;if(task.blocked)task.status='Ожидает данных'});save();render()}};
