// Демонстрационный набор для объекта «Жилой комплекс „Северный берег“».
// Данные сохраняются отдельно в контексте объекта и добавляются только один раз.
function ensureNorthernShoreShowcase(){
  const marker='northern-shore-showcase-v1';
  const project=state.projects?.find(item=>item.id==='residential');
  if(!project||project.showcaseSeed===marker)return false;
  let data=project.id===state.currentProjectId?projectSnapshot():cloneProjectData(project.data||projectInitialData(project));
  const structures=project.structures?.length?project.structures:['Корпус 1','Корпус 2'];
  const workKinds=['Устройство фундаментной плиты','Армирование вертикальных конструкций','Бетонирование стен подземной части','Монтаж монолитных колонн','Устройство наружной гидроизоляции','Монтаж плит перекрытия','Кладка наружных стен','Устройство кровельного покрытия','Прокладка внутренних инженерных сетей','Благоустройство прилегающей территории'];
  const stages=['Подготовка основания','Захватка А','Захватка Б','Секция 1','Секция 2'];
  const workStart=Math.max(0,...data.works.map(item=>Number(item.id)||0))+1;
  const works=workKinds.map((name,index)=>({
    id:workStart+index,code:'ЖК-СБ-02-'+String(index+21).padStart(3,'0'),date:`${String(2+index).padStart(2,'0')}.08.2026`,created:`${String(2+index).padStart(2,'0')}.08.2026, 10:${String(index).padStart(2,'0')}`,
    structure:structures[index%structures.length],section:stages[index%stages.length],construction:['фундамент','стены','колонны','перекрытие','кровля'][index%5],name,volume:[120,48,86,34,240,72,390,180,560,110][index],unit:index%3===0?'м³':index%3===1?'т':'м²',foreman:'Петров П.П.',ready:0,missing:0,aosr:'Черновик',state:'in-progress'
  }));
  data.works.push(...works);
  const rolePlans=[
    ['Производитель работ','Петров П.П.',['Внести запись в общий журнал работ','Подтвердить объём выполненных работ','Загрузить фотоматериалы по захватке','Оформить передачу фронта работ','Закрыть замечание по организации работ']],
    ['Геодезическая служба','Смирнов Д.В.',['Выполнить исполнительную съёмку','Загрузить исполнительную геодезическую схему','Проверить отметки конструкций','Передать геодезический отчёт','Подтвердить разбивочные оси']],
    ['Входной контроль','Кузнецов Р.О.',['Проверить паспорт качества материалов','Зарегистрировать сертификат соответствия','Оформить акт входного контроля','Проверить маркировку партии','Подтвердить допуск материала']],
    ['Строительная лаборатория','Орлов М.С.',['Отобрать контрольные образцы','Загрузить протокол испытаний','Провести контроль прочности','Оформить протокол уплотнения','Передать результаты испытаний']],
    ['Строительный контроль','Васильев А.Н.',['Проверить готовность к следующей операции','Подтвердить освидетельствование скрытых работ','Выдать замечание по качеству работ','Проверить устранение замечания','Согласовать промежуточную приёмку']],
    ['ПТО','Сидоров А.А.',['Проверить комплектность исполнительной документации','Сформировать реестр приложений','Подготовить проект АОСР','Проверить комплект перед выпуском','Передать АОСР на согласование']],
    ['Руководитель проекта','Иванов И.И.',['Проверить сводную готовность корпуса','Согласовать критический срок','Рассмотреть запрос на разблокировку АОСР','Назначить ответственного за замечание','Подтвердить выпуск комплекта ИД']],
    ['Администратор','Администратор системы',['Проверить доступ подрядчика к объекту','Настроить рабочее пространство участника','Проверить журнал действий','Актуализировать справочник объекта','Проконтролировать резервное копирование']]
  ];
  const statuses=['Новая','В работе','Ожидает данных','На проверке','Выполнена','Просрочена'];
  const priorities=['Средний','Высокий','Критичный','Высокий','Средний'];
  const taskBase=760000;
  const tasks=[];
  rolePlans.forEach(([dept,assignee,titles],roleIndex)=>titles.forEach((title,itemIndex)=>{
    const number=roleIndex*5+itemIndex;
    const work=works[number%works.length];
    const status=statuses[number%statuses.length];
    tasks.push({id:taskBase+number+1,title:`${title}: ${work.structure}, ${work.section}`,work:work.id,dept,assignee,due:`${String(5+(number%24)).padStart(2,'0')}.09.2026`,priority:priorities[itemIndex],status,ready:status==='Выполнена'?100:status==='На проверке'?85:status==='В работе'?55:status==='Ожидает данных'?30:status==='Просрочена'?25:0,stage:['ПТО','Руководитель проекта'].includes(dept)?2:1,attachments:[]});
  }));
  data.tasks.push(...tasks);
  const docKinds=['Исполнительная документация','Геодезические документы','Документы качества','Лабораторные протоколы'];
  const docTypes=['Исполнительная схема','Геодезический отчёт','Паспорт качества','Протокол испытаний'];
  const extensions=['pdf','pdf','pdf','xlsx','jpg'];
  const uploads=tasks.slice(0,36).map((task,index)=>{
    const work=works.find(item=>item.id===task.work);
    const kind=docKinds[index%docKinds.length];
    const status=['Принят','На проверке','Принят','Возвращён с замечаниями'][index%4];
    const file=`ЖК-СБ-02_${String(index+1).padStart(2,'0')}_${extensions[index%extensions.length]}.${extensions[index%extensions.length]}`;
    task.attachments.push(file);
    return {kind,name:`${docTypes[index%docTypes.length]} — ${work.structure}, ${work.section}`,number:`СБ-${String(index+1).padStart(3,'0')}/26`,date:`${String(3+(index%25)).padStart(2,'0')}.08.2026`,structure:work.structure,type:docTypes[index%docTypes.length],file,linkedWorks:[work.id],reviewStatus:status,reviewComment:status==='Возвращён с замечаниями'?'Требуется уточнить дату выполнения и приложить лист согласования.':'',reviewHistory:[{date:'10.08.2026',action:status,comment:''}]};
  });
  data.uploads.push(...uploads);
  data.audit.push({date:'10.08.2026',user:'Администратор системы',role:'Администратор',text:'Добавлен демонстрационный набор: 50 задач и 36 файлов для Жилого комплекса «Северный берег».',workId:works[0].id});
  project.data=data;
  project.showcaseSeed=marker;
  if(project.id===state.currentProjectId)projectDataFields.forEach(field=>state[field]=cloneProjectData(data[field]));
  return true;
}

// Кнопки оперативной работы на персональной главной должны оставаться
// рабочими независимо от того, какой вариант bind() сформировал экран.
// Делегирование на корневом документе не теряется при полной перерисовке SPA.
if (!window.__roleTaskFilterDelegationBound) {
  document.addEventListener('click', event => {
    const taskFilterButton = event.target.closest('[data-role-task-filter]');
    if (taskFilterButton) {
      event.preventDefault();
      event.stopImmediatePropagation();
      window.openRoleTaskFilter(taskFilterButton.dataset.roleTaskFilter);
      return;
    }

    if (event.target.closest('#clear-role-task-filter')) {
      event.preventDefault();
      event.stopImmediatePropagation();
      delete state.roleTaskFilter;
      save();
      render();
    }
  }, true);
  window.__roleTaskFilterDelegationBound = true;
}
window.openRoleTaskFilter = filter => {
  state.roleTaskFilter = filter;
  delete state.operationalFilter;
  state.page = 'Все задачи';
  save();
  // Открываем список напрямую: поздние оболочки render() не могут вернуть
  // пользователя на персональную главную вместо выбранного списка задач.
  app.innerHTML = tasksPage();
  bind();
  window.scrollTo({top:0,behavior:'smooth'});
};
window.addEventListener('hashchange', () => {
  const match = location.hash.match(/^#role-tasks=(.+)$/);
  if (!match) return;
  window.openRoleTaskFilter(decodeURIComponent(match[1]));
  history.replaceState(null, '', location.pathname + location.search);
});
function canManageProjects(){return ['Администратор','Руководитель проекта'].includes(currentAuthUser()?.role)}
function projectCreateModal(){if(!canManageProjects())return toast('Создание проектов доступно администратору и руководителю проекта.');modal('Новый объект строительства',`<p class="source">Для нового объекта будет создан отдельный комплект демонстрационных работ, задач, документов и АОСР.</p><div class="form-grid"><div class="field full"><label>Наименование объекта</label><input id="project-name" placeholder="Например, Жилой комплекс «Речной квартал»"></div><div class="field"><label>Шифр объекта</label><input id="project-code" placeholder="Например, ЖК-РК-04"></div><div class="field"><label>Сооружения / корпуса</label><textarea id="project-structures" placeholder="Каждое сооружение с новой строки&#10;Корпус 1&#10;Подземный паркинг"></textarea></div></div>`,`<button class="btn" data-close>Отмена</button><button class="btn btn-primary" id="save-project">Создать проект</button>`);$('#save-project').onclick=()=>{let name=$('#project-name').value.trim(),code=$('#project-code').value.trim().toUpperCase(),structures=$('#project-structures').value.split('\n').map(item=>item.trim()).filter(Boolean);if(!name||!code||!structures.length)return toast('Укажите наименование, шифр и хотя бы одно сооружение.');if(state.projects.some(project=>project.name.toLowerCase()===name.toLowerCase()||project.code.toLowerCase()===code.toLowerCase()))return toast('Проект с таким названием или шифром уже существует.');activeProject().data=projectSnapshot();let project={id:'project-'+Date.now(),name,code,structures};project.data=projectInitialData(project);state.projects.push(project);state.currentProjectId=project.id;projectDataFields.forEach(field=>state[field]=cloneProjectData(project.data[field]));state.page='Главная';modalRoot.innerHTML='';save();render();toast('Проект создан и открыт: '+name)}}
