function projectEditModal(id){let project=state.projects.find(item=>item.id===id);if(!project||!canManageProjects())return toast('Изменение проектов доступно администратору и руководителю проекта.');modal('Изменить объект строительства',`<div class="form-grid"><div class="field full"><label>Наименование объекта</label><input id="project-name" value="${auditEsc(project.name)}"></div><div class="field"><label>Шифр объекта</label><input id="project-code" value="${auditEsc(project.code)}"></div><div class="field"><label>Сооружения / корпуса</label><textarea id="project-structures">${auditEsc(project.structures.join('\n'))}</textarea></div></div>`,`<button class="btn" data-close>Отмена</button><button class="btn btn-primary" id="save-project">Сохранить</button>`);$('#save-project').onclick=()=>{let name=$('#project-name').value.trim(),code=$('#project-code').value.trim().toUpperCase(),structures=$('#project-structures').value.split('\n').map(item=>item.trim()).filter(Boolean);if(!name||!code||!structures.length)return toast('Укажите наименование, шифр и хотя бы одно сооружение.');if(state.projects.some(item=>(item.name.toLowerCase()===name.toLowerCase()||item.code.toLowerCase()===code.toLowerCase())&&item.id!==id))return toast('Проект с таким названием или шифром уже существует.');let data=project.id===state.currentProjectId?projectSnapshot():cloneProjectData(project.data||projectInitialData(project)),oldStructures=project.structures;data.works.forEach(work=>{let position=oldStructures.indexOf(work.structure);if(position>=0)work.structure=structures[Math.min(position,structures.length-1)]});project.name=name;project.code=code;project.structures=structures;project.data=data;if(project.id===state.currentProjectId)projectDataFields.forEach(field=>state[field]=cloneProjectData(data[field]));modalRoot.innerHTML='';save();render();toast('Параметры объекта сохранены.')}}
function deleteProject(id){if(!canManageProjects())return toast('Удаление проектов доступно администратору и руководителю проекта.');if(state.projects.length<2)return toast('Нельзя удалить единственный объект проекта.');let project=state.projects.find(item=>item.id===id);if(!project||!confirm('Удалить объект «'+project.name+'» вместе с его локальными данными?'))return;if(project.id===state.currentProjectId){project.data=projectSnapshot();let next=state.projects.find(item=>item.id!==id);state.projects=state.projects.filter(item=>item.id!==id);state.currentProjectId=next.id;if(!next.data)next.data=projectInitialData(next);projectDataFields.forEach(field=>state[field]=cloneProjectData(next.data[field]));state.page='Главная'}else state.projects=state.projects.filter(item=>item.id!==id);save();render();toast('Объект удалён.')}
const directoryDetailBeforeProjectLifecycle=directoryDetail;
directoryDetail=function(name){if(name!=='Объекты')return directoryDetailBeforeProjectLifecycle(name);let projects=state.projects,actions=canManageProjects()?'<button class="btn btn-primary" id="add-project-from-directory">＋ Добавить проект</button>':'';return shell(heading('Объекты','Реестр объектов строительства и переключение рабочего контекста',actions)+`<button class="btn btn-sm" id="back-to-directories">← Все разделы</button><div class="card" style="margin-top:12px"><div class="table-wrap"><table class="table"><thead><tr><th>Наименование</th><th>Шифр</th><th>Сооружения</th><th>Статус</th><th></th></tr></thead><tbody>${projects.map(project=>`<tr><td><b>${auditEsc(project.name)}</b></td><td>${auditEsc(project.code)}</td><td>${project.structures.length}</td><td><span class="status ${project.id===state.currentProjectId?'progress':'done'}">${project.id===state.currentProjectId?'Текущий объект':'Доступен'}</span></td><td><button class="action" data-project-open="${project.id}">${project.id===state.currentProjectId?'Открыт':'Открыть'}</button>${canManageProjects()?` <button class="action" data-project-edit="${project.id}">Изменить</button><button class="action" data-project-delete="${project.id}">Удалить</button>`:''}</td></tr>`).join('')}</tbody></table></div></div>`) };
