function localApiAvailable(){return !location.hostname.endsWith('.github.io')}
async function portalApi(path,options={}){let headers={...(options.headers||{})};if(state.auth?.token)headers.Authorization='Bearer '+state.auth.token;let response=await fetch('/api'+path,{...options,headers});let payload=await response.json().catch(()=>({}));if(!response.ok)throw new Error(payload.error||'Ошибка локального сервера.');return payload}
const bindLoginBeforeLocalApi=bindLogin;
bindLogin=function(){if(!localApiAvailable())return bindLoginBeforeLocalApi();let email=$('#login-email'),password=$('#login-password'),submit=$('#login-submit');if(!email||!password||!submit)return;let attempt=async()=>{submit.disabled=true;try{let result=await portalApi('/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:email.value.trim(),password:password.value})}),serverUser=result.user,localUser=state.users.find(user=>user.email?.toLowerCase()===serverUser.email.toLowerCase());if(!localUser){localUser={id:serverUser.id,name:serverUser.name,email:serverUser.email,role:serverUser.role,active:!!serverUser.active};state.users.push(localUser)}else Object.assign(localUser,{name:serverUser.name,email:serverUser.email,role:serverUser.role,active:!!serverUser.active});state.auth={loggedIn:true,userId:localUser.id,token:result.token};state.role=serverUser.role;state.page='Главная';save();render();toast('Выполнен вход: '+serverUser.name+' · '+serverUser.role)}catch(error){password.value='';toast(error.message)}finally{submit.disabled=false}};submit.onclick=attempt;password.onkeydown=event=>{if(event.key==='Enter')attempt()}}
const bindLogoutBeforeLocalApi=bind;
bind=function(){bindLogoutBeforeLocalApi();let logout=$('#logout');if(logout&&localApiAvailable())logout.onclick=async()=>{let token=state.auth?.token;try{if(token)await portalApi('/auth/logout',{method:'POST'})}catch(error){console.warn(error)}state.auth={loggedIn:false,userId:null};save();render()}};
