function fileAsBase64(file){return new Promise((resolve,reject)=>{let reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(new Error('Не удалось прочитать выбранный файл.'));reader.readAsDataURL(file)})}
const uploadModalBeforeLocalStorage=uploadModal;
uploadModal=function(){uploadModalBeforeLocalStorage();let saveButton=$('#save-doc'),input=$('#file-input');if(!saveButton||!input||!localApiAvailable())return;let originalSave=saveButton.onclick;saveButton.onclick=async()=>{let file=input.files?.[0];if(!file)return originalSave();saveButton.disabled=true;try{let result=await portalApi('/files',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:file.name,content_base64:await fileAsBase64(file),project_id:activeProject()?.id})}),countBefore=state.uploads.length;originalSave();if(state.uploads.length>countBefore){state.uploads[0].storageId=result.id;state.uploads[0].sizeBytes=result.size_bytes;save()}toast('Файл сохранён в локальном хранилище и направлен на проверку.')}catch(error){toast(error.message)}finally{saveButton.disabled=false}}};
render();
function liveWorkStatus(work){
  const tasks=state.tasks.filter(task=>task.work===work.id);
  const done=tasks.filter(task=>task.status==='Выполнена').length;
  const ready=tasks.length?Math.round(done/tasks.length*100):Number(work.ready||0);
  const missing=Math.max(tasks.length-done,0);
  const overdue=tasks.some(task=>task.status==='Просрочена');
  const aosrTask=tasks.find(task=>task.matrixKey==='aosr'||task.dept==='ПТО');
  const allDone=tasks.length>0&&done===tasks.length;
  let aosr='Ожидает документов';
  if(allDone)aosr='Подписан';
  else if(aosrTask?.blocked)aosr='Ожидает документов';
  else if(aosrTask?.status==='На проверке')aosr='На проверке';
  else if(aosrTask?.status==='В работе')aosr='Черновик';
  else if(!tasks.length)aosr=work.aosr||'Черновик';
  return {tasks,done,ready,missing,aosr,overdue};
}
function liveMetrics(){let works=state.works.map(work=>({work,status:liveWorkStatus(work)})),tasks=state.tasks,uploads=state.uploads,ready=works.length?Math.round(works.reduce((sum,item)=>sum+item.status.ready,0)/works.length):0;return {works,tasks,uploads,ready,completedWorks:works.filter(item=>item.status.ready===100).length,activeTasks:tasks.filter(task=>!task.blocked&&task.status!=='Выполнена').length,overdue:tasks.filter(task=>!task.blocked&&task.status==='Просрочена').length,reviewDocs:uploads.filter(doc=>(doc.reviewStatus||'На проверке')==='На проверке').length,returnedDocs:uploads.filter(doc=>doc.reviewStatus==='Возвращён с замечаниями').length,aosrCreated:works.filter(item=>['Сформирован','На проверке','Подписан'].includes(item.status.aosr)).length,aosrSigned:works.filter(item=>item.status.aosr==='Подписан').length}}
worksTable=function(works,short=false){return `<div class="table-wrap"><table class="table"><thead><tr><th>№</th><th>Работа / сооружение</th>${short?'':'<th>Дата выполнения</th><th>Объём</th><th>Производитель</th>'}<th>Готовность ИД</th><th>АОСР</th><th>Просрочка</th><th></th></tr></thead><tbody>${works.map(work=>{let live=liveWorkStatus(work);return `<tr><td><b>${work.code}</b></td><td><b>${work.name}</b><br><span style="color:var(--muted)">${work.structure} · ${work.section}</span></td>${short?'':`<td>${work.date}<br><span style="color:var(--muted)">${work.created}</span></td><td>${work.volume} ${work.unit}</td><td>${work.foreman}</td>`}<td><span class="progress-line"><i style="width:${live.ready}%"></i></span> ${live.ready}%</td><td><span class="status ${statusClass(live.aosr)}">${live.aosr}</span></td><td>${live.overdue?'<span class="status overdue">есть</span>':'—'}</td><td><button class="action" data-work="${work.id}">Открыть</button></td></tr>`}).join('')||'<tr><td colspan="9" class="empty-note">Работы по объекту пока не зарегистрированы.</td></tr>'}</tbody></table></div>`};
dashboard=function(){let m=liveMetrics(),project=activeProject(),attention=m.works.filter(item=>item.status.missing>0||item.status.overdue).slice(0,4);return shell(heading('Главная',`Оперативные показатели объекта: ${project.name}`,`<div class="role-switch"><select id="role">${roles.map(role=>`<option ${role===state.role?'selected':''}>${role}</option>`).join('')}</select></div>`)+`<div class="kpis"><div class="kpi"><div class="kpi-label">Выполнено работ</div><div class="kpi-value">${m.works.length}</div></div><div class="kpi"><div class="kpi-label">Полностью готово по ИД</div><div class="kpi-value">${m.completedWorks}</div></div><div class="kpi"><div class="kpi-label">Средняя готовность ИД</div><div class="kpi-value">${m.ready}%</div></div><div class="kpi"><div class="kpi-label">АОСР сформировано</div><div class="kpi-value">${m.aosrCreated}</div></div><div class="kpi"><div class="kpi-label">АОСР подписано</div><div class="kpi-value">${m.aosrSigned}</div></div><div class="kpi"><div class="kpi-label">Активные задачи</div><div class="kpi-value">${m.activeTasks}</div></div><div class="kpi"><div class="kpi-label">Просрочено задач</div><div class="kpi-value" style="color:var(--red)">${m.overdue}</div></div><div class="kpi"><div class="kpi-label">Документы на проверке</div><div class="kpi-value">${m.reviewDocs}</div></div></div><div class="grid-2"><div><div class="card"><div class="card-head"><h2>Готовность ИД по сооружениям</h2><button class="action" data-page="Сооружения">Открыть →</button></div><div class="chart">${activeProject().structures.map(name=>{let rows=m.works.filter(item=>item.work.structure===name),value=rows.length?Math.round(rows.reduce((sum,item)=>sum+item.status.ready,0)/rows.length):0;return `<div class="bar-col"><div class="bar" style="height:${value}%"><em>${value}%</em></div><span>${auditEsc(name)}</span></div>`}).join('')}</div></div><div class="card"><div class="card-head"><h2>Последние работы</h2><button class="action" data-page="Выполненные работы">Реестр →</button></div>${worksTable(state.works.slice(0,4),true)}</div></div><div><div class="card"><h2>Оперативный контроль</h2>${operationalControlPanel()}</div><div class="card"><h2>Требуют внимания</h2>${attention.map(item=>`<button class="critical ${item.status.overdue?'':'orange'}" data-work="${item.work.id}"><b>${auditEsc(item.work.name)}</b><br><span>${item.status.overdue?'Есть просроченная задача. ':''}Незавершённых задач: ${item.status.missing}.</span></button>`).join('')||'<p class="empty-note">Критических отклонений нет.</p>'}</div></div></div>`) };
reportsPage=function(){let m=liveMetrics(),byDepartment=Object.entries(m.tasks.reduce((map,task)=>{if(task.status==='Просрочена')map[task.dept]=(map[task.dept]||0)+1;return map},{})),withoutId=m.works.filter(item=>item.status.ready<100).length,reports=[['Средняя готовность ИД',m.ready+'%','по задачам выбранного объекта'],['Просрочки по подразделениям',m.overdue,byDepartment.map(item=>item[0]+' · '+item[1]).join(', ')||'нет'],['Активные задачи',m.activeTasks,'без выполненных и заблокированных'],['Документы с замечаниями',m.returnedDocs,'требуют повторной проверки'],['Сформировано АОСР',m.aosrCreated,'подписано: '+m.aosrSigned],['Работы без полного ИД',withoutId,'требуют завершения задач']];return shell(heading('Отчёты',`Аналитика выбранного объекта: ${activeProject().name}`)+`<div class="report-grid">${reports.map((row,index)=>`<button class="report" data-operational-page="${index===1||index===2?'Все задачи':index===3?'Документы качества':index===4?'АОСР':'Выполненные работы'}"><b>${row[0]}</b><div class="num" style="color:${index===1&&m.overdue?'var(--red)':'var(--ink)'}">${row[1]}</div><small style="color:var(--muted);display:block;margin-top:8px">${row[2]}</small></button>`).join('')}</div><div class="card" style="margin-top:18px"><h2>Распределение незавершённых задач</h2><div class="chart">${Object.entries(m.tasks.filter(task=>task.status!=='Выполнена').reduce((map,task)=>{map[task.status]=(map[task.status]||0)+1;return map},{})).map(([name,count])=>`<div class="bar-col"><div class="bar" style="height:${Math.min(100,count/Math.max(1,m.tasks.length)*240)}px"><em>${count}</em></div><span>${name}</span></div>`).join('')||'<p class="empty-note">Незавершённых задач нет.</p>'}</div></div>`) };
structuresPage=function(){let project=activeProject(),items=project.structures.map(name=>{let rows=state.works.filter(work=>work.structure===name),statuses=rows.map(liveWorkStatus),ready=rows.length?Math.round(statuses.reduce((sum,item)=>sum+item.ready,0)/rows.length):0,overdue=statuses.filter(item=>item.overdue).length;return {name,rows,ready,overdue}});return shell(heading('Сооружения',`Текущий статус по объекту: ${project.name}`)+`<div class="report-grid">${items.map(item=>`<button class="report" data-project-structure="${auditEsc(item.name)}"><b>${auditEsc(item.name)}</b><div class="num">${item.ready}%</div><div class="mini-bar"><i style="width:${item.ready}%"></i></div><small style="color:var(--muted);display:block;margin-top:8px">Работ: ${item.rows.length} · просроченных задач: ${item.overdue}</small></button>`).join('')}</div>`) };
const uploadModalBeforeRequireFile=uploadModal;
uploadModal=function(){uploadModalBeforeRequireFile();let saveButton=$('#save-doc'),input=$('#file-input');if(!saveButton||!input||!localApiAvailable())return;let previous=saveButton.onclick;saveButton.onclick=()=>{if(!input.files?.[0])return toast('Выберите файл для загрузки.');previous()}};
const loginPageBeforeLiveLabel=loginPage;
loginPage=function(){return loginPageBeforeLiveLabel().replace('Демонстрационный режим: учётные данные хранятся только в локальном браузере.',localApiAvailable()?'Локальный режим: учётные записи проверяются сервером этого компьютера.':'Демонстрационный режим: данные и учётные записи хранятся только в вашем браузере.')};
const workJournalPageBeforeLiveHeader=workJournalPage;
workJournalPage=function(){let project=activeProject();return workJournalPageBeforeLiveHeader().replace('Объект: строительство гидротехнического сооружения','Объект: '+auditEsc(project.name)).replace('Застройщик: демонстрационные данные','Застройщик: не указан')};
render();
projectInitialData=function(){return {works:[],tasks:[],uploads:[],audit:[],workJournal:[],workFilter:{structure:'',status:'',overdue:''},documentFilters:{}}};
const aosrTemplateCatalogBeforeLiveLabel=aosrTemplateCatalog;
aosrTemplateCatalog=function(){return aosrTemplateCatalogBeforeLiveLabel().replace('Демонстрационные шаблоны','Библиотека шаблонов').replace('Демонстрационные шаблоны по рекомендуемому образцу','Рабочие шаблоны по рекомендуемому образцу')};
const aosrTemplateDetailBeforeLiveObject=aosrTemplateDetail;
aosrTemplateDetail=function(key){return aosrTemplateDetailBeforeLiveObject(key).replace('Заполненный демонстрационный шаблон АОСР','Рабочий шаблон АОСР').replace('Строительство гидротехнического сооружения',auditEsc(activeProject().name))};
const previewUnavailableActionBeforeLiveStorage=previewUnavailableAction;
previewUnavailableAction=function(button){let label=button.textContent.trim()||'элемент';if(button.classList.contains('action'))return toast('Для «'+label+'» нет связанного файла или записи в реестре.');return previewUnavailableActionBeforeLiveStorage(button)};
async function downloadStoredDocument(id,name){try{let response=await fetch('/api/files/'+encodeURIComponent(id),{headers:{Authorization:'Bearer '+(state.auth?.token||'')}});if(!response.ok)throw new Error('Файл недоступен.');let url=URL.createObjectURL(await response.blob()),link=document.createElement('a');link.href=url;link.download=name||'документ';link.click();URL.revokeObjectURL(url)}catch(error){toast(error.message)}}
const bindStoredDocuments=bind;
bind=function(){bindStoredDocuments();document.querySelectorAll('.action').forEach(button=>{let documentItem=state.uploads.find(item=>item.storageId&&item.file===button.textContent.trim());if(documentItem)button.onclick=()=>downloadStoredDocument(documentItem.storageId,documentItem.file)})};
render();
operationalControlPanel=function(){let m=liveMetrics(),blocked=blockedAosrTasks().length;return `<div class="card operational-panel"><div class="card-head"><div><h2>Оперативный контроль</h2><p class="source">Показатели выбранного объекта</p></div><span class="source">Обновляется при изменении данных</span></div><div class="report-grid"><button class="report" data-operational-filter="active"><b>Активные задачи</b><div class="num">${m.activeTasks}</div><small>без выполненных и заблокированных</small></button><button class="report" data-operational-filter="overdue"><b>Просрочено</b><div class="num" style="color:var(--red)">${m.overdue}</div><small>требует контроля</small></button><button class="report" data-operational-filter="blocked-aosr"><b>АОСР ожидают условий</b><div class="num" style="color:var(--orange)">${blocked}</div><small>не завершены зависимые задачи</small></button><button class="report" data-operational-filter="returned-docs"><b>Документы с замечаниями</b><div class="num" style="color:var(--red)">${m.returnedDocs}</div><small>требуют доработки</small></button></div></div>`};
const tasksPageBeforeOperationalFilter=tasksPage;
tasksPage=function(mine=false){let filter=state.operationalFilter,originalTasks=state.tasks;if(!mine&&filter==='active')state.tasks=originalTasks.filter(task=>!task.blocked&&task.status!=='Выполнена');if(!mine&&filter==='overdue')state.tasks=originalTasks.filter(task=>!task.blocked&&task.status==='Просрочена');let html=tasksPageBeforeOperationalFilter(mine);state.tasks=originalTasks;if(!mine&&(filter==='active'||filter==='overdue')){let label=filter==='active'?'активные задачи':'просроченные задачи';html=html.replace('<div class="card"><div class="tabs">',`<div class="source" style="margin-bottom:12px">Показан фильтр: <b>${label}</b> <button class="btn btn-sm" id="clear-operational-filter">Сбросить</button></div><div class="card"><div class="tabs">`)}return html};
const aosrPageBeforeOperationalFilter=aosrPage;
aosrPage=function(){let originalWorks=state.works;if(state.operationalFilter==='blocked-aosr'){let allowedIds=new Set(blockedAosrTasks().map(task=>task.work));state.works=originalWorks.filter(work=>allowedIds.has(work.id))}let html=aosrPageBeforeOperationalFilter();state.works=originalWorks;if(state.operationalFilter==='blocked-aosr')html=html.replace('<div class="card">','<div class="source" style="margin-bottom:12px">Показаны АОСР, ожидающие выполнения зависимых задач. <button class="btn btn-sm" id="clear-operational-filter">Сбросить</button></div><div class="card">');return html};
const bindOperationalFilters=bind;
bind=function(){bindOperationalFilters();let duplicate=$('#operational-panel');if(duplicate&&document.querySelector('.operational-panel'))duplicate.remove();document.querySelectorAll('[data-operational-filter]').forEach(button=>button.onclick=()=>{let filter=button.dataset.operationalFilter;state.operationalFilter=filter;if(filter==='returned-docs'){state.documentFilters['Документы качества']={...(state.documentFilters['Документы качества']||{}),status:'Возвращён с замечаниями'};state.page='Документы качества'}else state.page=filter==='blocked-aosr'?'АОСР':'Все задачи';save();render()});let clear=$('#clear-operational-filter');if(clear)clear.onclick=()=>{delete state.operationalFilter;if(state.page==='Документы качества')state.documentFilters['Документы качества']={status:'',query:''};save();render()}};
render();
state.sidebarCollapsed ||= false;
const shellBeforeSidebarToggle=shell;
shell=function(content){let html=shellBeforeSidebarToggle(content),collapsed=state.sidebarCollapsed;html=html.replace('<div class="shell">',`<div class="shell ${collapsed?'sidebar-collapsed':''}">`);return html.replace('<aside class="sidebar">',`<aside class="sidebar"><button class="sidebar-toggle" id="sidebar-toggle" title="${collapsed?'Развернуть':'Свернуть'} боковую панель" aria-label="${collapsed?'Развернуть':'Свернуть'} боковую панель">${collapsed?'»':'«'}</button>`)};
const bindSidebarToggle=bind;
bind=function(){bindSidebarToggle();let button=$('#sidebar-toggle');if(button)button.onclick=()=>{state.sidebarCollapsed=!state.sidebarCollapsed;save();render()}};
render();
async function downloadServerBackup(){try{let response=await fetch('/api/admin/backup',{headers:{Authorization:'Bearer '+(state.auth?.token||'')}});if(!response.ok){let payload=await response.json().catch(()=>({}));throw new Error(payload.error||'Не удалось сформировать резервную копию.')}let url=URL.createObjectURL(await response.blob()),link=document.createElement('a');link.href=url;link.download='stroi_portal_backup.zip';link.click();URL.revokeObjectURL(url);toast('Серверная резервная копия скачана.')}catch(error){toast(error.message)}}
