dashboard=function(){return dashboardBeforeOperationalLayout().replace('<div class="card"><h2>Оперативный контроль</h2><div class="card operational-panel">','<div class="card operational-panel">').replace('</div></div><div class="card"><h2>Требуют внимания</h2>','</div><div class="card"><h2>Требуют внимания</h2>')};
render();

// Набор задач для демонстрации полного маршрута исполнительной документации.
// Добавляется один раз в текущий объект и не затрагивает уже созданные пользователем задачи.
